package com.adc.infrastructure;

import com.adc.domain.analytics.AnalyticsRules;
import com.adc.domain.shared.BusinessTime;
import com.adc.application.QuarterlyPerformanceService;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service
public class AnalyticsSnapshotReader {
    private final AnalyticsStore store;private final QuarterlyPerformanceStore performance;private final AnalyticsEvidence evidence;private static final JsonMapper JSON=JsonMapper.builder().build();
    public AnalyticsSnapshotReader(AnalyticsStore store,QuarterlyPerformanceStore performance,AnalyticsEvidence evidence){this.store=store;this.performance=performance;this.evidence=evidence;}
    private static String text(Map<String,Object> row,String key){return (String)row.get(key);}
    private static long id(Map<String,Object> row,String key){return Long.parseLong(text(row,key));}
    private static void ratio(Map<String,Object> result,long numerator,long denominator){result.put("numerator",Long.toString(numerator));result.put("denominator",Long.toString(denominator));result.put("value",AnalyticsRules.ratio(numerator,denominator));if(denominator==0)result.put("not_computable_reason","ZERO_DENOMINATOR");}
    private static void unavailable(Map<String,Object> result,String reason){result.put("value",null);result.put("not_computable_reason",reason);result.put("missing_count",Math.max(1,(Integer)result.get("missing_count")));}
    private record Outcome(List<Map<String,Object>> rows,Object sources){}
    @Transactional(propagation=Propagation.REQUIRES_NEW,isolation=Isolation.REPEATABLE_READ,readOnly=true)
    public Map<String,Object> read(AnalyticsStore.Selection selection){
        var result=new LinkedHashMap<String,Object>();result.put("metric",selection.metric());result.put("start",selection.start().toString());result.put("end",selection.end().toString());result.put("cutoff",selection.cutoff().toString());result.put("rule_version","A1a-B13");result.put("value",null);result.put("numerator",null);result.put("denominator",null);for(String key:List.of("sample_count","excluded_count","missing_count","unprocessed_count"))result.put(key,0);result.put("provisional",selection.end().isAfter(selection.cutoff()));result.put("not_computable_reason",null);
        Outcome outcome;if(store.historicalStateUnavailable(selection)){unavailable(result,"SOURCE_SNAPSHOT_UNAVAILABLE");outcome=new Outcome(List.of(),List.of());}else outcome=switch(selection.metric()){case "cancellations"->cancellations(selection,result);case "treatment-comparison"->comparison(selection,result);case "traceability"->traceability(selection,result);case "skill-slot-coverage"->skills(selection,result);case "skill-structure"->structure(selection,result);case "performance"->performances(selection,result);case "coverage"->coverage(selection,result);case "calculation-time"->calculationTime(selection,result);default->throw new IllegalArgumentException("Unknown metric");};
        result.put("rows",outcome.rows);String digest=HexFormat.of().formatHex(Crypto.sha256(CanonicalJson.normalize(JSON.writeValueAsString(Map.of("selection",selection,"sources",outcome.sources,"evidence",evidence.reference(),"rule_version","A1a-B13","result",result)))));result.put("source_references",List.of("snapshot:sha256:"+digest,evidence.reference()));return result;
    }
    private Outcome cancellations(AnalyticsStore.Selection s,Map<String,Object> result){
        var facts=store.appointments(s);var rows=new TreeMap<Long,long[]>();var used=new ArrayList<Object>();int sample=0,excluded=0,pending=0,missing=0;for(var row:facts){var slotEnd=Instant.parse(text(row,"scheduled_at")).plusSeconds(id(row,"slot_minutes")*60);if(slotEnd.isAfter(s.cutoff()))continue;sample++;var counts=rows.computeIfAbsent(id(row,"clinic_id"),k->new long[7]);counts[0]++;var events=store.events(id(row,"appointment_id"),s.cutoff());var frozenRow=new LinkedHashMap<>(row);if(row.get("cancelled_at")!=null && Instant.parse(text(row,"cancelled_at")).isAfter(s.cutoff())){frozenRow.put("cancelled_at",null);frozenRow.put("cancellation_kind",null);}used.add(Map.of("appointment",frozenRow,"events",events));if(events.isEmpty()){missing++;counts[5]++;continue;}String state=text(events.getLast(),"to_status");String kind=state.equals("CANCELLED")?text(row,"cancellation_kind"):null;if(state.equals("CANCELLED") && (row.get("cancelled_at")==null || Instant.parse(text(row,"cancelled_at")).isAfter(s.cutoff()) || kind==null)){missing++;counts[5]++;continue;}if("CLINIC_CANCEL".equals(kind) || "CLINIC_RESCHEDULE".equals(kind)){excluded++;counts[1]++;continue;}counts[2]++;if("PATIENT_CANCEL".equals(kind))counts[3]++;else if("NO_SHOW".equals(kind))counts[4]++;if(state.equals("SCHEDULED")){pending++;counts[6]++;}}
        long patients=rows.values().stream().mapToLong(c->c[3]).sum(),absence=rows.values().stream().mapToLong(c->c[4]).sum(),denominator=rows.values().stream().mapToLong(c->c[2]).sum();var projection=new ArrayList<Map<String,Object>>();for(var entry:rows.entrySet()){var c=entry.getValue();var row=new LinkedHashMap<String,Object>();row.put("clinic_id",entry.getKey().toString());row.put("ended_count",Long.toString(c[0]));row.put("excluded_count",Long.toString(c[1]));row.put("denominator",Long.toString(c[2]));row.put("patient_cancel_count",Long.toString(c[3]));row.put("no_show_count",Long.toString(c[4]));row.put("unprocessed_count",Long.toString(c[6]));row.put("patient_cancel_rate",AnalyticsRules.ratio(c[3],c[2]));row.put("no_show_rate",AnalyticsRules.ratio(c[4],c[2]));row.put("non_fulfillment_rate",AnalyticsRules.ratio(c[3]+c[4],c[2]));projection.add(row);}result.put("sample_count",sample);result.put("excluded_count",excluded);result.put("missing_count",missing);result.put("unprocessed_count",pending);ratio(result,patients+absence,denominator);if(pending>0)result.put("provisional",true);if(missing>0)unavailable(result,"INCOMPLETE_APPOINTMENT_HISTORY");return new Outcome(projection,used);
    }
    private Outcome comparison(AnalyticsStore.Selection s,Map<String,Object> result){var facts=store.treatments(s);record Key(String clinic,String treatment){}var groups=new LinkedHashMap<Key,List<Map<String,Object>>>();for(var row:facts)groups.computeIfAbsent(new Key(text(row,"clinic_id"),text(row,"treatment_id")),k->new ArrayList<>()).add(row);var rows=new ArrayList<Map<String,Object>>();var allSubtotal=new BigDecimal("0.00");var allUnits=new BigDecimal("0.00");for(var entry:groups.entrySet()){var units=entry.getValue().stream().map(r->new BigDecimal(text(r,"standard_units"))).reduce(new BigDecimal("0.00"),BigDecimal::add);var subtotal=entry.getValue().stream().map(r->new BigDecimal(text(r,"subtotal"))).reduce(new BigDecimal("0.00"),BigDecimal::add);var row=new LinkedHashMap<String,Object>();row.put("clinic_id",entry.getKey().clinic);row.put("treatment_id",entry.getKey().treatment);row.put("unit_definition_reference","Treatment:"+entry.getKey().treatment);row.put("count",Integer.toString(entry.getValue().size()));row.put("standard_units",units.setScale(2).toPlainString());row.put("subtotal",subtotal.setScale(2).toPlainString());row.put("weighted_unit_price",AnalyticsRules.weighted(subtotal,units));rows.add(row);allSubtotal=allSubtotal.add(subtotal);allUnits=allUnits.add(units);}result.put("sample_count",facts.size());if(groups.keySet().stream().map(Key::treatment).distinct().count()>1)unavailable(result,"DIFFERENT_TREATMENT_UNITS_NOT_COMPARABLE");else{result.put("value",AnalyticsRules.weighted(allSubtotal,allUnits));result.put("numerator",allSubtotal.setScale(2).toPlainString());result.put("denominator",allUnits.setScale(2).toPlainString());if(allUnits.signum()==0)result.put("not_computable_reason","ZERO_DENOMINATOR");}return new Outcome(rows,facts);}
    private Outcome traceability(AnalyticsStore.Selection s,Map<String,Object> result){var facts=store.treatments(s);long complete=0;var missing=new TreeMap<String,Integer>();var keys=List.of("patient_id","appointment_id","dentist_id","treatment_id","standard_units","unit_price","performed_at");for(var row:facts){var values=keys.stream().map(row::get).toList();if(AnalyticsRules.traceable(values))complete++;else for(String key:keys)if(row.get(key)==null)missing.merge(key,1,Integer::sum);}result.put("sample_count",facts.size());result.put("missing_count",facts.size()-Math.toIntExact(complete));ratio(result,complete,facts.size());var row=new LinkedHashMap<String,Object>();row.put("valid_treatment_count",Integer.toString(facts.size()));row.put("seven_facts_complete_count",Long.toString(complete));row.put("missing_elements",missing);return new Outcome(List.of(row),facts);}
    private Outcome skills(AnalyticsStore.Selection s,Map<String,Object> result){if(s.treatment()==null || !store.treatmentExists(s.treatment())){unavailable(result,"TREATMENT_REQUIRED");return new Outcome(List.of(),List.of());}var facts=store.schedules(s);var groups=new TreeMap<Long,long[]>();for(var row:facts){var day=LocalDate.parse(text(row,"schedule_date"));var start=LocalTime.parse(text(row,"start_time"));var end=LocalTime.parse(text(row,"end_time"));int minutes=Math.toIntExact(id(row,"slot_minutes"));var counts=groups.computeIfAbsent(id(row,"clinic_id"),k->new long[2]);boolean qualified=store.qualified(id(row,"dentist_id"),id(row,"clinic_id"),day,s.treatment());for(var slot=day.atTime(start).atZone(BusinessTime.ZONE).toInstant();slot.isBefore(day.atTime(end).atZone(BusinessTime.ZONE).toInstant());slot=slot.plusSeconds(minutes*60L)){if(slot.isBefore(s.start()) || !slot.isBefore(s.end()))continue;counts[1]++;if(qualified)counts[0]++;}}long qualified=groups.values().stream().mapToLong(c->c[0]).sum(),total=groups.values().stream().mapToLong(c->c[1]).sum();result.put("sample_count",Math.toIntExact(total));ratio(result,qualified,total);var rows=new ArrayList<Map<String,Object>>();for(var entry:groups.entrySet()){var row=new LinkedHashMap<String,Object>();row.put("clinic_id",entry.getKey().toString());row.put("treatment_id",s.treatment().toString());row.put("qualified_normal_slots",Long.toString(entry.getValue()[0]));row.put("normal_slots",Long.toString(entry.getValue()[1]));row.put("coverage",AnalyticsRules.ratio(entry.getValue()[0],entry.getValue()[1]));rows.add(row);}return new Outcome(rows,Map.of("schedules",facts,"eligibility",store.skillEvidence(s)));}
    private Outcome structure(AnalyticsStore.Selection s,Map<String,Object> result){var facts=store.qualifications(s);result.put("sample_count",facts.size());result.put("value",Integer.toString(facts.size()));var rows=new ArrayList<Map<String,Object>>();for(var source:facts){var row=new LinkedHashMap<>(source);row.put("meaning","QUALIFICATION_HISTORY_NOT_TREATMENT_CAPACITY");rows.add(row);}return new Outcome(rows,facts);}
    private static boolean naturalQuarter(AnalyticsStore.Selection s){var from=s.start().atZone(BusinessTime.ZONE);var until=s.end().atZone(BusinessTime.ZONE);return from.toLocalTime().equals(LocalTime.MIDNIGHT) && until.toLocalTime().equals(LocalTime.MIDNIGHT) && from.getDayOfMonth()==1 && (from.getMonthValue()-1)%3==0 && until.toLocalDate().equals(from.toLocalDate().plusMonths(3));}
    private Outcome performances(AnalyticsStore.Selection s,Map<String,Object> result){if(!naturalQuarter(s)){unavailable(result,"NATURAL_QUARTER_REQUIRED");return new Outcome(List.of(),List.of());}var all=performance.all().stream().filter(r->!LocalDate.parse(r.start()).isBefore(s.start().atZone(BusinessTime.ZONE).toLocalDate()) && !LocalDate.parse(r.end()).isAfter(s.end().atZone(BusinessTime.ZONE).toLocalDate()) && (s.dentist()==null || r.dentist()==s.dentist())).toList();var rows=new ArrayList<Map<String,Object>>();var refs=new ArrayList<Object>();var seen=new HashSet<String>();int missing=0;for(var row:all){if(!row.status().equals("PUBLISHED"))continue;var input=QuarterlyPerformanceService.input(row);if(!s.clinics().containsAll(input.clinics()))continue;String key=row.dentist()+"/"+row.start();if(!seen.add(key)){unavailable(result,"MULTIPLE_CURRENT_PUBLICATIONS");return new Outcome(List.of(),List.of());}if(row.published()==null || Instant.parse(row.published()).isAfter(s.cutoff()) || !"R1".equals(input.rule()) || !row.hash().equals(QuarterlyPerformanceService.hash(input))){missing++;continue;}rows.add(Map.of("dentist_id",Long.toString(row.dentist()),"quarter_start",row.start(),"quarter_end",row.end(),"quarterly_performance_id",Long.toString(row.id()),"calculation_status","PUBLISHED","revenue",row.revenue(),"medical_supply_cost",row.medical(),"operating_expense",row.operating(),"net_profit",row.profit(),"incentive_amount",row.incentive()));refs.add(Map.of("performance_id",Long.toString(row.id()),"input_hash",row.hash(),"rule_version","R1"));}var eligible=all.stream().filter(r->s.clinics().containsAll(QuarterlyPerformanceService.input(r).clinics())).map(r->r.dentist()+"/"+r.start()).distinct().count();missing+=Math.toIntExact(Math.max(0,eligible-seen.size()));result.put("sample_count",rows.size());result.put("missing_count",missing);result.put("unprocessed_count",missing);if(rows.isEmpty())unavailable(result,"NO_COMPARABLE_CURRENT_PUBLICATION");else if(missing>0){result.put("provisional",true);result.put("not_computable_reason","UNPUBLISHED_OR_INCOMPARABLE_PEOPLE");}return new Outcome(rows,refs);}
    private Outcome coverage(AnalyticsStore.Selection s,Map<String,Object> result){var roster=evidence.roster(s.start(),s.end(),s.cutoff());if(roster.isEmpty()){unavailable(result,"OPERATING_ROSTER_UNAVAILABLE");return new Outcome(List.of(),List.of());}var operating=roster.get().clinic_ids().stream().map(Long::parseLong).filter(s.clinics()::contains).distinct().sorted().toList();var appointments=store.appointments(s);var treatments=store.treatments(s);long used=0;var rows=new ArrayList<Map<String,Object>>();for(long clinic:operating){boolean patient=store.patientUsage(clinic,s)>0,appointment=appointments.stream().anyMatch(r->id(r,"clinic_id")==clinic),treatment=treatments.stream().anyMatch(r->id(r,"clinic_id")==clinic);boolean unified=patient && appointment && treatment;if(unified)used++;rows.add(Map.of("clinic_id",Long.toString(clinic),"patient_usage_evidence",patient,"appointment_usage_evidence",appointment,"treatment_usage_evidence",treatment,"unified_use",unified));}result.put("sample_count",operating.size());result.put("missing_count",operating.size()-Math.toIntExact(used));ratio(result,used,operating.size());if(used<operating.size())unavailable(result,"DATA_USAGE_EVIDENCE_INCOMPLETE");return new Outcome(rows,Map.of("roster",roster.get(),"usage",rows));}
    private Outcome calculationTime(AnalyticsStore.Selection s,Map<String,Object> result){if(!naturalQuarter(s)){unavailable(result,"NATURAL_QUARTER_REQUIRED");return new Outcome(List.of(),List.of());}var all=performance.all().stream().filter(r->r.status().equals("PUBLISHED") && r.start().equals(s.start().atZone(BusinessTime.ZONE).toLocalDate().toString()) && r.end().equals(s.end().atZone(BusinessTime.ZONE).toLocalDate().toString()) && s.clinics().containsAll(QuarterlyPerformanceService.input(r).clinics())).toList();if(all.isEmpty()){unavailable(result,"COMPLETE_PUBLICATION_UNAVAILABLE");return new Outcome(List.of(),List.of());}var first=all.getFirst();var snapshot=JSON.readTree(first.snapshot());var input=QuarterlyPerformanceService.input(first);if(all.stream().anyMatch(r->!r.hash().equals(first.hash())) || all.size()!=input.personnel().size() || input.preparer()==null){unavailable(result,"INCOMPLETE_PUBLICATION_BATCH");return new Outcome(List.of(),List.of());}var ready=Instant.parse(snapshot.get("verified_at").asText());var published=all.stream().map(r->Instant.parse(r.published())).max(Comparator.naturalOrder()).orElseThrow();if(published.isAfter(s.cutoff())){unavailable(result,"SOURCE_SNAPSHOT_UNAVAILABLE");return new Outcome(List.of(),List.of());}var calendar=evidence.calendar(ready,published,s.cutoff());var row=new LinkedHashMap<String,Object>();row.put("ready_at",ready.toString());row.put("all_published_at",published.toString());row.put("waiting_for_evidence","RECORDED_SEPARATELY");if(calendar.isEmpty())unavailable(result,"WORKDAY_CALENDAR_UNAVAILABLE");else{String days=AnalyticsEvidence.workingDays(ready,published,calendar.get());result.put("value",days);row.put("working_days",days);row.put("calendar_reference",calendar.get().reference());}result.put("sample_count",all.size());return new Outcome(List.of(row),Map.of("input_hash",first.hash(),"ready",ready.toString(),"published",published.toString(),"calendar",calendar.<Object>map(c->c).orElse("UNAVAILABLE")));}
}
